script:
(function () {
  'use strict';
  // Annuity accumulation, stepped monthly. The annual growth rate r is an effective yearly rate, so
  // the monthly rate is (1 + r)^(1/12) - 1. Yearly additions land at the start or end of each year,
  // monthly additions at the start or end of each month (annuity due vs ordinary annuity).
  // Payout estimate: level monthly payment that runs the ending balance to $0 over the payout years,
  //   PMT = B x j / (1 - (1 + j)^-n), divided by (1 + j) when paid at the start of each month,
  //   with j = (1 + payout rate)^(1/12) - 1 and n = payout years x 12.
  // Checked in Node (an.test.js): $20,000 + $10,000 a year at the start, 6%, 10 years = $175,533.38
  // (= 20000 x 1.06^10 + 10000 x 1.06 x (1.06^10 - 1) / 0.06; also the default result shown by a
  // competitor's annuity calculator); end-of-year version = $167,624.90; monthly additions only,
  // $200 for 10 years at 0% = $24,000; $100,000 paid out over 20 years at 4% gives a payment whose
  // present value equals $100,000 and leaves a $0 balance after 240 months.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var OUTPUTS = ['anBalance', 'anAdded', 'anGrowth', 'anIncome', 'anStartOut', 'anShare', 'anPaidOut', 'anPayLength'];

  // --- calc start
  // p: start, annual, monthly, rate (decimal, effective yearly), years, due (bool)
  function accumulate(p) {
    var j = Math.pow(1 + p.rate, 1 / 12) - 1;
    var bal = p.start, added = 0, rows = [], yAdd = 0, yGrowth = 0;
    for (var m = 1; m <= p.years * 12; m++) {
      var monthStart = 0, monthEnd = 0;
      if (p.due) { monthStart += p.monthly; if (m % 12 === 1) monthStart += p.annual; }
      else { monthEnd += p.monthly; if (m % 12 === 0) monthEnd += p.annual; }
      bal += monthStart;
      var g = bal * j;
      bal += g + monthEnd;
      added += monthStart + monthEnd; yAdd += monthStart + monthEnd; yGrowth += g;
      if (m % 12 === 0) { rows.push({ year: m / 12, added: yAdd, growth: yGrowth, balance: bal }); yAdd = 0; yGrowth = 0; }
    }
    return { balance: bal, added: added, rows: rows };
  }

  function payout(balance, rate, years, due) {
    var j = Math.pow(1 + rate, 1 / 12) - 1, n = years * 12;
    var pmt = j === 0 ? balance / n : balance * j / (1 - Math.pow(1 + j, -n));
    if (due) pmt /= 1 + j;
    return pmt;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function fail(msg) {
    var error = document.getElementById('anError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('anSchedule').innerHTML = '';
  }

  function update() {
    var start = num('anStart'), annual = num('anAnnual'), monthly = num('anMonthly'), rate = num('anRate'),
        years = num('anYears'), payYears = num('anPayYears'), payRate = num('anPayRate');
    var due = document.getElementById('anTiming').value === 'begin';
    document.getElementById('anError').hidden = true;
    if ([start, annual, monthly, rate, years, payYears, payRate].some(isNaN)) return fail('Fill in every field with a number (0 is fine for amounts you do not use).');
    if (start < 0 || annual < 0 || monthly < 0) return fail('Amounts cannot be negative.');
    if (start + annual + monthly <= 0) return fail('Enter a starting principal or an addition.');
    if (rate < 0 || rate > 30 || payRate < 0 || payRate > 30) return fail('Enter growth rates from 0 to 30%.');
    years = Math.round(years); payYears = Math.round(payYears);
    if (years < 1 || years > 60) return fail('Enter 1 to 60 years to grow.');
    if (payYears < 1 || payYears > 50) return fail('Enter a payout period of 1 to 50 years.');
    var r = accumulate({ start: start, annual: annual, monthly: monthly, rate: rate / 100, years: years, due: due });
    var pmt = payout(r.balance, payRate / 100, payYears, due);
    var growth = r.balance - start - r.added;
    document.getElementById('anBalance').textContent = money.format(r.balance);
    document.getElementById('anAdded').textContent = money.format(r.added);
    document.getElementById('anGrowth').textContent = money.format(growth);
    document.getElementById('anIncome').textContent = money.format(pmt);
    document.getElementById('anStartOut').textContent = money.format(start);
    document.getElementById('anShare').textContent = (r.balance > 0 ? growth / r.balance * 100 : 0).toFixed(1) + '%';
    document.getElementById('anPaidOut').textContent = money.format(pmt * payYears * 12);
    document.getElementById('anPayLength').textContent = payYears + (payYears === 1 ? ' year' : ' years') + ' (' + payYears * 12 + ' payments)';
    document.getElementById('anSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.added) + '</td><td>' +
             money.format(row.growth) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('anForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
